<?php
include('../config.php');
require_once __DIR__ . '/../base/GuildPolicy.class.php';
$pagegen = new page_gen(); $pagegen->round_to = 4; $pagegen->start();
$s = new Game();
if (!$s->loggedIn || !isset($_GET['time'])) { header('Location: ../index.php'); exit; }
$db = $s->db_link; $uid = (int)$_SESSION['userid'];
function guild_h($v): string { return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
if (empty($_SESSION['guild_csrf'])) $_SESSION['guild_csrf'] = bin2hex(random_bytes(16));
$csrf = $_SESSION['guild_csrf']; $notice = ''; $error = '';
$meQ = $db->query("SELECT u.uname,u.allyid,gm.rank_level FROM users u LEFT JOIN guild_members gm ON gm.uid=u.uid WHERE u.uid=$uid LIMIT 1");
$me = $meQ ? $meQ->fetch_assoc() : []; $guildId = (int)($me['allyid'] ?? 0); $rank = (int)($me['rank_level'] ?? 0);
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    if (!hash_equals($csrf, (string)($_POST['csrf'] ?? ''))) $error = 'Security validation failed. Refresh and retry.';
    else {
        $action = (string)($_POST['guild_action'] ?? '');
        if ($action === 'create') {
            if ($guildId > 0) $error = 'You already belong to a guild.';
            else {
                $name = trim((string)($_POST['guild_name'] ?? '')); $tag = strtoupper(trim((string)($_POST['guild_tag'] ?? ''))); $desc = trim((string)($_POST['description'] ?? ''));
                if (!preg_match('/^[A-Za-z0-9 ]{3,80}$/', $name) || !preg_match('/^[A-Z0-9]{2,12}$/', $tag)) $error = 'Guild name or tag is invalid.';
                else { $st = $db->prepare('INSERT INTO guilds (guild_name,guild_tag,description,founder_uid) VALUES (?,?,?,?)'); $st->bind_param('sssi',$name,$tag,$desc,$uid); if($st->execute()){ $guildId=(int)$db->insert_id; $st=$db->prepare('INSERT INTO guild_members (guild_id,uid,rank_level) VALUES (?,?,4)'); $st->bind_param('ii',$guildId,$uid); $st->execute(); $st=$db->prepare('UPDATE users SET allyid=?,arank=2 WHERE uid=?'); $st->bind_param('ii',$guildId,$uid); $st->execute(); $rank=4; $notice='Guild founded: '.$name.'.'; } else $error='Guild creation failed; name or tag may already be in use.'; }
            }
        } elseif ($action === 'invite') {
            $target=(int)($_POST['target_uid']??0); if($guildId<=0||!GuildPolicy::canManage($rank))$error='Only guild officers can invite members.'; elseif($target<=0||$target===$uid)$error='Choose a valid player.'; else { $countQ=$db->query("SELECT COUNT(*) c FROM guild_members WHERE guild_id=$guildId"); $count=(int)($countQ?($countQ->fetch_assoc()['c']??0):0); if($count>=GuildPolicy::MAX_MEMBERS)$error='Guild capacity reached: 150 members.'; else { $expires=date('Y-m-d H:i:s',time()+604800); $st=$db->prepare("INSERT INTO guild_invites (guild_id,invited_uid,invited_by,expires_at) VALUES (?,?,?,?)");$st->bind_param('iiis',$guildId,$target,$uid,$expires); if($st->execute())$notice='Invitation transmitted.';else$error='Invitation already pending or invalid.'; } }
        } elseif ($action === 'accept') {
            $invite=(int)($_POST['invite_id']??0); if($guildId>0)$error='Leave your current guild before joining another.'; else { $st=$db->prepare("SELECT guild_id FROM guild_invites WHERE invite_id=? AND invited_uid=? AND status='pending' AND expires_at>NOW() LIMIT 1");$st->bind_param('ii',$invite,$uid);$st->execute();$row=$st->get_result()->fetch_assoc(); if(!$row)$error='Invitation expired or unavailable.'; else {$g=(int)$row['guild_id'];$cQ=$db->query("SELECT COUNT(*) c FROM guild_members WHERE guild_id=$g");$c=(int)($cQ?($cQ->fetch_assoc()['c']??0):0);if($c>=GuildPolicy::MAX_MEMBERS)$error='Guild capacity reached.';else{$st=$db->prepare('INSERT INTO guild_members (guild_id,uid,rank_level) VALUES (?, ?, 1)');$st->bind_param('ii',$g,$uid);$st->execute();$st=$db->prepare('UPDATE users SET allyid=?,arank=0 WHERE uid=?');$st->bind_param('ii',$g,$uid);$st->execute();$db->query("UPDATE guild_invites SET status='accepted' WHERE invite_id=$invite");$guildId=$g;$rank=1;$notice='Invitation accepted.';}} }
        } elseif ($action === 'claim_territory') {
            $sector = strtoupper(trim((string)($_POST['sector_code'] ?? '')));
            if ($guildId <= 0 || !GuildPolicy::canManageOfficers($rank)) $error = 'Only Marshal-level officers can claim territory.';
            elseif (!preg_match('/^[A-Z0-9:_-]{2,32}$/', $sector)) $error = 'Enter a valid sector code.';
            else { $st=$db->prepare('INSERT INTO guild_territories (guild_id,sector_code,claimed_by) VALUES (?,?,?)'); $st->bind_param('isi',$guildId,$sector,$uid); if($st->execute()){$notice='Territory claimed for guild influence.';}else{$error='That sector is already claimed or unavailable.';} }
        } elseif ($action === 'contribute') {
            $amount=max(0,min((int)($_POST['amount']??0),GuildPolicy::MAX_DAILY_CONTRIBUTION)); if($guildId<=0||$amount<=0)$error='Enter a valid contribution amount.';else{$bQ=$db->query("SELECT onHand FROM bank WHERE uid=$uid LIMIT 1");$on=(int)($bQ?($bQ->fetch_assoc()['onHand']??0):0);if($on<$amount)$error='Insufficient credits.';else{$db->query("UPDATE bank SET onHand=onHand-$amount WHERE uid=$uid LIMIT 1");$db->query("UPDATE guilds SET shared_credits=shared_credits+$amount,contribution_score=contribution_score+$amount WHERE guild_id=$guildId");$st=$db->prepare('UPDATE guild_members SET contribution_total=contribution_total+?,last_active_at=NOW() WHERE guild_id=? AND uid=?');$st->bind_param('iii',$amount,$guildId,$uid);$st->execute();$notice='Contribution deposited into the guild treasury.';}} }
    }
}
$guild = $guildId>0 ? (($q=$db->query("SELECT * FROM guilds WHERE guild_id=$guildId LIMIT 1"))?$q->fetch_assoc():[]) : [];
$memberCount=0;$members=false;$territories=false;$bonuses=GuildPolicy::bonus(0,1,0);if($guild){$cQ=$db->query("SELECT COUNT(*) c FROM guild_members WHERE guild_id=$guildId");$memberCount=(int)($cQ?($cQ->fetch_assoc()['c']??0):0);$members=$db->query("SELECT gm.uid,gm.rank_level,gm.contribution_total,u.uname FROM guild_members gm INNER JOIN users u ON u.uid=gm.uid WHERE gm.guild_id=$guildId ORDER BY gm.rank_level DESC,gm.contribution_total DESC LIMIT 150");$territories=$db->query("SELECT sector_code,control_points,status,claimed_at FROM guild_territories WHERE guild_id=$guildId ORDER BY control_points DESC,territory_id DESC LIMIT 50");$bonuses=GuildPolicy::bonus($memberCount,(int)$guild['guild_level'],(int)$guild['contribution_score']);}
echo '<div class="comm-shell"><div class="page-hub-head"><span class="rts-kicker">UNIVERSE CIVILIZATION // GUILD COMMAND</span><h3>Guild Operations Console</h3><p>Coordinate up to 150 commanders through shared bonuses, treasury contributions, and officer-controlled membership.</p></div>';
if($notice)echo '<div class="comm-alert">'.guild_h($notice).'</div>';if($error)echo '<div class="comm-alert comm-error">'.guild_h($error).'</div>';
if(!$guild){echo '<section class="comm-card"><h4>Found a Guild</h4><form method="post" action="modules/guild.php?time='.time().'"><input type="hidden" name="csrf" value="'.guild_h($csrf).'"/><input type="hidden" name="guild_action" value="create"/><label>Guild Name<input name="guild_name" maxlength="80" required></label><label>Guild Tag<input name="guild_tag" maxlength="12" required></label><label>Mission Statement<textarea name="description" maxlength="500"></textarea></label><button class="comm-btn">Found Guild</button></form></section>';}else{echo '<div class="comm-grid"><section class="comm-card"><h4>'.guild_h($guild['guild_name']).' ['.guild_h($guild['guild_tag']).']</h4><p>'.guild_h($guild['description']).'</p><p><b>Roster:</b> '.number_format($memberCount).' / '.GuildPolicy::MAX_MEMBERS.'<br><b>Guild Level:</b> '.(int)$guild['guild_level'].'<br><b>Treasury:</b> '.number_format((int)$guild['shared_credits']).' credits</p></section><section class="comm-card"><h4>Guild Bonuses</h4><p>Production +'.$bonuses['production_percent'].'% · Defense +'.$bonuses['defense_percent'].'% · Research +'.$bonuses['research_percent'].'% · Fleet Recovery +'.$bonuses['fleet_recovery_percent'].'%</p><form method="post" action="modules/guild.php?time='.time().'" class="inline-form"><input type="hidden" name="csrf" value="'.guild_h($csrf).'"/><input type="hidden" name="guild_action" value="contribute"/><input type="number" name="amount" min="1" max="'.GuildPolicy::MAX_DAILY_CONTRIBUTION.'" placeholder="Credits" required><button class="comm-btn">Contribute</button></form></section><section class="comm-card"><h4>Territory Influence</h4><p>Claim sector codes to establish guild influence zones and strategic staging areas.</p><div class="admin-table-wrap"><table><tr><th>Sector</th><th>Control Points</th><th>Status</th></tr>';if($territories)while($t=$territories->fetch_assoc())echo '<tr><td>'.guild_h($t['sector_code']).'</td><td>'.number_format((int)$t['control_points']).'</td><td>'.guild_h(ucfirst((string)$t['status'])).'</td></tr>';echo '</table></div>'.(GuildPolicy::canManageOfficers($rank)?'<form method="post" action="modules/guild.php?time='.time().'" class="inline-form"><input type="hidden" name="csrf" value="'.guild_h($csrf).'"/><input type="hidden" name="guild_action" value="claim_territory"/><input name="sector_code" maxlength="32" placeholder="G1:SECTOR-01" required><button class="comm-btn">Claim Sector</button></form>':'').'</section><section class="comm-card"><h4>150-Member Roster</h4><div class="admin-table-wrap"><table><tr><th>UID</th><th>Commander</th><th>Rank</th><th>Contribution</th></tr>';if($members)while($m=$members->fetch_assoc())echo '<tr><td>'.(int)$m['uid'].'</td><td>'.guild_h($m['uname']).'</td><td>'.guild_h(GuildPolicy::ranks()[(int)$m['rank_level']]??'Member').'</td><td>'.number_format((int)$m['contribution_total']).'</td></tr>';echo '</table></div></section>';if(GuildPolicy::canManage($rank))echo '<section class="comm-card"><h4>Officer Tools</h4><form method="post" action="modules/guild.php?time='.time().'" class="inline-form"><input type="hidden" name="csrf" value="'.guild_h($csrf).'"/><input type="hidden" name="guild_action" value="invite"/><input type="number" name="target_uid" min="1" placeholder="Player UID" required><button class="comm-btn">Invite Commander</button></form></section>';}
echo '</div>'; $pagegen->stop(); print('page generation time: '.$pagegen->gen()); ?>
